<?php class ProdukController extends CrudController{function __construct(){$this->table='produk';$this->title='Produk';$this->fields=['kode'=>'Kode','nama'=>'Nama produk','kategori_id'=>'Kategori','supplier_id'=>'Supplier','harga'=>'Harga','stok'=>'Stok'];$this->view='produk';}function nextCode(){$db=Database::connect();for($n=1;;$n++){$code='EF-'.str_pad($n,3,'0',STR_PAD_LEFT);$s=$db->prepare('SELECT COUNT(*) FROM produk WHERE kode=?');$s->execute([$code]);if(!$s->fetchColumn())return $code;}}function upload(){if(empty($_FILES['gambar']['name'])||$_FILES['gambar']['error']!==UPLOAD_ERR_OK||$_FILES['gambar']['size']>2097152)return null;$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['gambar']['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))return null;$name=uniqid('produk_',true).'.'.$allowed[$mime];move_uploaded_file($_FILES['gambar']['tmp_name'],__DIR__.'/../../uploads/products/'.$name);return $name;}function index(){require_admin();$db=Database::connect();$q=trim($_GET['q']??'');$page=max(1,(int)($_GET['p']??1));$limit=10;$where=$q?' WHERE p.nama LIKE ? OR p.kode LIKE ?':'';$params=$q?["%$q%","%$q%"]:[];$s=$db->prepare("SELECT COUNT(*) FROM produk p{$where}");$s->execute($params);$total=(int)$s->fetchColumn();$pages=max(1,(int)ceil($total/$limit));$page=min($page,$pages);$s=$db->prepare("SELECT p.*,k.nama kategori_nama,s.nama supplier_nama FROM produk p LEFT JOIN kategori k ON k.id=p.kategori_id LEFT JOIN supplier s ON s.id=p.supplier_id{$where} ORDER BY p.id DESC LIMIT {$limit} OFFSET ".(($page-1)*$limit));$s->execute($params);$rows=$s->fetchAll();$pageTitle='Produk';require __DIR__.'/../views/produk/index.php';}function create(){require_admin();$this->options();$row=['kode'=>$this->nextCode()];$pageTitle='Tambah Produk';require __DIR__.'/../views/produk/form.php';}function store(){require_admin();$_POST['kode']=$this->nextCode();$cols=['kode','nama','kategori_id','supplier_id','harga','stok'];$s=Database::connect()->prepare('INSERT INTO produk('.implode(',',$cols).') VALUES(?,?,?,?,?,?)');$s->execute(array_map(fn($x)=>$_POST[$x]??null,$cols));$id=Database::connect()->lastInsertId();if($file=$this->upload())Database::connect()->prepare('UPDATE produk SET gambar=? WHERE id=?')->execute([$file,$id]);flash('success','Produk berhasil ditambahkan.');redirect('?page=produk');}function edit(){require_admin();$this->options();$s=Database::connect()->prepare('SELECT * FROM produk WHERE id=?');$s->execute([$_GET['id']]);$row=$s->fetch();$pageTitle='Edit Produk';require __DIR__.'/../views/produk/form.php';}function update(){require_admin();$cols=['kode','nama','kategori_id','supplier_id','harga','stok'];$s=Database::connect()->prepare('UPDATE produk SET '.implode('=?,',$cols).'=? WHERE id=?');$s->execute([...array_map(fn($x)=>$_POST[$x]??null,$cols),$_POST['id']]);if($file=$this->upload())Database::connect()->prepare('UPDATE produk SET gambar=? WHERE id=?')->execute([$file,$_POST['id']]);flash('success','Produk berhasil diperbarui.');redirect('?page=produk');}}
